-- =====================================================================
-- 매칭 평가용 정답 · 함정 공고 91건 (AI-A 생성 · 원본 ai/eval/postings/out/eval_postings.json)
-- 이 파일은 build_postings_sql.py 가 만든다. 직접 고치지 말고 spec.json → render_postings.py → 이 스크립트 순서로 다시 만든다.
-- 실행: mysql -u <계정> -p ieum < ai/eval/postings/out/eval_postings.sql   (schema.sql · seed.sql 실행 뒤)
-- - id 900201~900291 고정, source 'EVAL', external_id 'eval-<id>'. 형식은 ai/data/eval/eval_jobs.sql (AI-B 일반 공고 150건)과 같다
-- - 다시 실행해도 중복되지 않는다: ON DUPLICATE KEY UPDATE 로 같은 id 를 덮어쓴다
-- - content_hash = SHA-256(description), job_code = application.yml it-job-codes, raw = NULL
-- - is_active = 마감일이 2026-10-29 이후면 1. BE 배치는 source 'SEOUL_API' 만 끄므로 이 공고는 켜진 채 남는다
-- 빼기: DELETE FROM job_posting WHERE source = 'EVAL' AND id BETWEEN 900201 AND 900300;
-- 주의: id 를 직접 넣으므로 AUTO_INCREMENT 가 900292 로 올라간다. 공고 배치(BE-A)보다 **먼저** 실행한다.
--       배치 공고가 먼저 900201 이후 id 를 받으면 이 파일이 그 공고를 덮어쓴다.
-- 모든 회사 · 주소 · 본문은 가상 데이터, 연락처는 [연락처 생략].
-- =====================================================================
USE ieum;
SET NAMES utf8mb4;

AS new
ON DUPLICATE KEY UPDATE
  company_name = new.company_name,
  title = new.title,
  job_code = new.job_code,
  job_category = new.job_category,
  location = new.location,
  work_address = new.work_address,
  employment_type = new.employment_type,
  career = new.career,
  education = new.education,
  salary_text = new.salary_text,
  description = new.description,
  deadline_on = new.deadline_on,
  until_filled = new.until_filled,
  posted_on = new.posted_on,
  is_active = new.is_active,
  content_hash = new.content_hash,
  synced_at = NOW();
